#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>

#define SCREEN_WIDTH 128
#define SCREEN_HEIGHT 64
#define OLED_ADDRESS 0x3C   // Поменяй на 0x3D, если не работает

Adafruit_SSD1306 display(SCREEN_WIDTH, SCREEN_HEIGHT, &Wire, -1);

// --- Параметры шрифта ---
const int charW = 6;
const int charH = 8;
const int cols = SCREEN_WIDTH / charW;  // 21 символ в строку

// --- Виртуальный холст ---
const int MAX_LINES = 40;
String lines[MAX_LINES];
int lineCount = 0;

void addLine(const String &text) {
  if (lineCount < MAX_LINES) {
    lines[lineCount] = text;
    lineCount++;
  }
}

// Добавляет метку и символы из диапазона кодов, разбивая по cols
void addCharRange(int startCode, int endCode, const char *label) {
  addLine(label);
  String buf = "";
  for (int code = startCode; code <= endCode; code++) {
    buf += (char)code;
    if (buf.length() >= cols) {
      addLine(buf);
      buf = "";
    }
  }
  if (buf.length() > 0) {
    addLine(buf);
  }
}

void drawWithOffset(int yOffset) {
  display.clearDisplay();
  display.setTextColor(SSD1306_WHITE);
  display.setTextSize(1);
  display.setTextWrap(false);

  for (int i = 0; i < lineCount; i++) {
    int y = i * charH + yOffset;
    // Пропускаем строки, которые полностью вне экрана
    if (y > -charH && y < SCREEN_HEIGHT) {
      display.setCursor(0, y);
      display.print(lines[i]);
    }
  }
  display.display();
}

void setup() {
  Serial.begin(9600);
  Serial.println(F("=== OLED CHAR VIEWER ==="));

  // Инициализация дисплея
  if (!display.begin(SSD1306_SWITCHCAPVCC, OLED_ADDRESS)) {
    Serial.println(F("ERROR: дисплей не найден!"));
    Serial.println(F("Проверь адрес (0x3C или 0x3D) и подключение SDA/SCL."));
    for (;;);  // зависаем
  }
  Serial.println(F("Дисплей инициализирован."));

  // Тестовый экран — чтобы сразу видеть, что дисплей жив
  display.clearDisplay();
  display.setTextSize(2);
  display.setTextColor(SSD1306_WHITE);
  display.setCursor(10, 20);
  display.print("HELLO!");
  display.display();
  delay(1500);

  // --- Заполняем виртуальный холст ---
  addLine("== ALL ASCII 32-126 ==");
  addLine("");

  addCharRange('A', 'Z', "A-Z:");
  addCharRange('a', 'z', "a-z:");
  addCharRange('0', '9', "0-9:");
  addCharRange(33, 47,  "Punct 33-47:");   // ! " # $ % & ' ( ) * + , - . /
  addCharRange(58, 64,  "Punct 58-64:");   // : ; < = > ? @
  addCharRange(91, 96,  "Punct 91-96:");   // [ \ ] ^ _
  addCharRange(123, 126,"Punct 123-126:"); // { | } ~

  Serial.print(F("Строк создано: "));
  Serial.println(lineCount);
  Serial.print(F("Высота холста: "));
  Serial.print(lineCount * charH);
  Serial.println(F(" px"));
}

void loop() {
  int totalHeight = lineCount * charH;
  int maxScroll = totalHeight - SCREEN_HEIGHT;

  if (maxScroll <= 0) {
    // Всё помещается — выводим без прокрутки
    drawWithOffset(0);
    delay(2000);
    return;
  }

  // Плавная прокрутка вниз
  for (int offset = 0; offset >= -maxScroll; offset -= 2) {
    drawWithOffset(offset);
    delay(50);
  }
  delay(1500);

  // Плавная прокрутка наверх
  for (int offset = -maxScroll; offset <= 0; offset += 2) {
    drawWithOffset(offset);
    delay(50);
  }
  delay(1500);
}
